// The native packages' generated files, written from the sources the web reads: the palette
// (DS1/1-root/palette.ts), the measures (DS1/1-root/measures.ts), the surface colours of the
// component tokens (DS1/1-root/component-tokens.css) and the icon names (DS1/x-icon).
// scripts/write-native-tokens.ts writes them; tests/native-tokens.test.ts fails when a committed
// file is stale. Never edit a generated file: change its source and run the script.
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { palette } from '../DS1/1-root/palette';
import { measures } from '../DS1/1-root/measures';

const root = fileURLToPath(new URL('..', import.meta.url));
const read = (path: string) => readFileSync(root + path, 'utf8');
export const appleGenerated = 'native/apple/Sources/DS1/Generated';

const header = (source: string) =>
  `// Generated by scripts/write-native-tokens.ts from ${source}.\n// Do not edit: change the source and run \`vp run native:tokens\`.\n`;

/** `Tuned red` → `tunedRed`, `shield-alt` → `shieldAlt`, `1x` → `icon1x`. */
export function swiftName(words: string, prefix = 'icon') {
  const parts = words.split(/[^A-Za-z0-9]+/).filter(Boolean);
  const name = parts.map((p, i) => (i ? p[0].toUpperCase() : p[0].toLowerCase()) + p.slice(1)).join('');
  return /^[0-9]/.test(name) ? prefix + name : name;
}
const keywords = new Set(['default', 'repeat', 'in', 'return', 'case', 'import', 'switch', 'class', 'struct', 'enum', 'protocol', 'func', 'var', 'let', 'if', 'else', 'for', 'while', 'do', 'break', 'continue', 'true', 'false', 'nil', 'self', 'super', 'init', 'is', 'as', 'try', 'throw', 'where', 'operator', 'extension', 'internal', 'public', 'private', 'static', 'subscript', 'typealias', 'guard', 'defer', 'fallthrough', 'inout', 'Type', 'Any', 'Self']);
const identifier = (name: string) => (keywords.has(name) ? `\`${name}\`` : name);
const hex = (value: string) => `0x${value.slice(1).toLowerCase()}`;

/** A colour as written in the CSS: `#rrggbb` or `#rrggbbaa`. */
type Css = { hex: string; alpha: number };
function colour(value: string): Css {
  const m = /^#([0-9a-f]{6})([0-9a-f]{2})?$/i.exec(value.trim());
  if (!m) throw new Error(`Not a colour: ${value}`);
  return { hex: `#${m[1].toLowerCase()}`, alpha: m[2] ? Math.round((parseInt(m[2], 16) / 255) * 1000) / 1000 : 1 };
}

/** The custom properties of the first `:root` block of a stylesheet. */
function rootProperties(css: string) {
  const start = css.indexOf(':root {');
  const block = css.slice(start, css.indexOf('\n}', start));
  const properties = new Map<string, string>();
  for (const m of block.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/(--[\w-]+):\s*([^;]+);/g)) properties.set(m[1], m[2].replace(/\s+/g, ' ').trim());
  return properties;
}

/** A property's light and dark values, following `var()` and `light-dark()`. */
function lightDark(properties: Map<string, string>, name: string): [Css, Css] {
  const resolve = (value: string): string => {
    const v = /^var\((--[\w-]+)\)$/.exec(value.trim());
    if (!v) return value.trim();
    const next = properties.get(v[1]);
    if (!next) throw new Error(`${v[1]} is not declared`);
    return resolve(next);
  };
  const value = resolve(properties.get(name) ?? (() => { throw new Error(`${name} is not declared`); })());
  const ld = /^light-dark\((.+)\)$/.exec(value);
  if (!ld) return [colour(value), colour(value)];
  // The comma between the two values, outside any parentheses of their own.
  let depth = 0;
  let split = -1;
  for (let i = 0; i < ld[1].length && split < 0; i++) {
    if (ld[1][i] === '(') depth++;
    else if (ld[1][i] === ')') depth--;
    else if (ld[1][i] === ',' && !depth) split = i;
  }
  return [colour(resolve(ld[1].slice(0, split))), colour(resolve(ld[1].slice(split + 1)))];
}

/** The surfaces the component tokens define, as their Swift names. */
export const surfaces: [string, string, string][] = [
  ['paper', '--ds-paper', 'The page.'],
  ['text', '--ds-text-color', 'Text.'],
  ['textMuted', '--ds-text-color-muted', 'Quieter text.'],
  ['title', '--ds-title-color', 'Titles and table headers.'],
  ['danger', '--ds-danger-color', 'Text that reports a failure or warns of a loss.'],
  ['border', '--ds-border-color', 'Outlines.'],
  ['fill', '--ds-fill', 'A control on the paper.'],
  ['fillHover', '--ds-fill-hover', 'A control under the pointer.'],
  ['focusRing', '--ds-focus-ring', 'The focus ring.'],
  ['accent', '--ds-accent-color', 'The accent: a primary button, a meaningful state.'],
  ['onAccent', '--ds-button-text-color-on-accent', 'Text on the accent.'],
  ['inputBackground', '--ds-input-background', 'A field.'],
  ['inputText', '--ds-input-color', 'Text in a field.'],
  ['inputPlaceholder', '--ds-input-placeholder-color', 'A field’s placeholder.'],
];

function swiftColour(light: Css, dark: Css) {
  const alpha = light.alpha !== 1 || dark.alpha !== 1 ? `, lightOpacity: ${light.alpha}, darkOpacity: ${dark.alpha}` : '';
  return `DS1Color(light: ${hex(light.hex)}, dark: ${hex(dark.hex)}${alpha})`;
}

export function paletteSwift() {
  const lines = [header('DS1/1-root/palette.ts and the surfaces of DS1/1-root/component-tokens.css'), 'extension DS1Color {'];
  const entries: string[] = [];
  for (const c of palette()) {
    const name = swiftName(c.name);
    const pastel = swiftName(c.pastelName);
    lines.push(`    /// ${c.name}: ${c.hex}, ${c.dark} in dark mode.`);
    lines.push(`    public static let ${identifier(name)} = ${swiftColour(colour(c.hex), colour(c.dark))}`);
    lines.push(`    /// ${c.pastelName}: ${c.pastel}, dimmed to ${c.dim} in dark mode.`);
    lines.push(`    public static let ${identifier(pastel)} = ${swiftColour(colour(c.pastel), colour(c.dim))}`);
    entries.push(`        DS1PaletteEntry(name: ${JSON.stringify(c.name)}, colour: .${identifier(name)}, pastelName: ${JSON.stringify(c.pastelName)}, pastel: .${identifier(pastel)}, ink: ${c.ink}),`);
  }
  const properties = rootProperties(read('DS1/1-root/component-tokens.css'));
  lines.push('');
  for (const [name, token, doc] of surfaces) {
    const [light, dark] = lightDark(properties, token);
    lines.push(`    /// ${doc} \`${token}\`.`);
    lines.push(`    public static let ${identifier(name)} = ${swiftColour(light, dark)}`);
  }
  lines.push('', '    /// The palette in its order around the wheel, then the inks, lightest first.', '    public static let palette: [DS1PaletteEntry] = [', ...entries, '    ]', '}', '');
  return lines.join('\n');
}

export function metricsSwift() {
  const lines = [header('DS1/1-root/measures.ts'), 'import CoreGraphics', '', '/// Design system 1’s measures at a scale of 1, in points. Multiply a length by `DS1Scale`.', 'public enum DS1Metrics {'];
  const walk = (value: Record<string, unknown>, path: string[]) => {
    for (const [key, v] of Object.entries(value)) {
      const name = swiftName([...path, key].join(' '));
      if (typeof v === 'object' && v) walk(v as Record<string, unknown>, [...path, key]);
      else if (key === 'decimals') lines.push(`    public static let ${identifier(name)}: Int = ${v}`);
      else lines.push(`    public static let ${identifier(name)}: CGFloat = ${v}`);
    }
  };
  walk(measures as unknown as Record<string, unknown>, []);
  lines.push('}', '');
  return lines.join('\n');
}

export function iconNames() {
  return readdirSync(root + 'DS1/x-icon').filter(f => f.endsWith('.svg')).map(f => f.slice(0, -4)).sort();
}

export function iconsSwift() {
  const lines = [header('the files in DS1/x-icon'), '/// Every icon in Design system 1’s library, by its file name.', 'public enum DS1IconName: String, CaseIterable, Sendable {'];
  for (const name of iconNames()) {
    const swift = swiftName(name);
    lines.push(swift === name ? `    case ${identifier(swift)}` : `    case ${identifier(swift)} = ${JSON.stringify(name)}`);
  }
  lines.push('}', '');
  return lines.join('\n');
}

/** Every generated Swift file, by its path in the repository. */
export function appleTokenFiles(): Record<string, string> {
  return {
    [`${appleGenerated}/Palette.swift`]: paletteSwift(),
    [`${appleGenerated}/Metrics.swift`]: metricsSwift(),
    [`${appleGenerated}/Icons.swift`]: iconsSwift(),
  };
}
